const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/webhooks/hooks/%7Bhook_id%7D/deliveries',
  qs: {
    company_id: 'SOME_INTEGER_VALUE',
    project_id: 'SOME_INTEGER_VALUE',
    page_size: 'SOME_INTEGER_VALUE',
    page_start: 'SOME_INTEGER_VALUE',
    'filters[status]': 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/webhooks/hooks/%7Bhook_id%7D/deliveries?company_id=SOME_INTEGER_VALUE&project_id=SOME_INTEGER_VALUE&page_size=SOME_INTEGER_VALUE&page_start=SOME_INTEGER_VALUE&filters%5Bstatus%5D=SOME_STRING_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
